import{_ as t,o as r,c as n,ah as s}from"./chunks/framework.ChH6X6u6.js";const c=JSON.parse('{"title":"Enseignement supérieur : filières et maquettes","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/enseignement-superieur.md","filePath":"src/guide/admin/enseignement-superieur.md"}'),a={name:"guide/admin/enseignement-superieur.md"};function i(o,e,l,u,p,d){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="enseignement-superieur-filieres-et-maquettes" tabindex="-1">Enseignement supérieur : filières et maquettes <a class="header-anchor" href="#enseignement-superieur-filieres-et-maquettes" aria-label="Permalink to &quot;Enseignement supérieur : filières et maquettes&quot;">​</a></h1><p>Si votre établissement délivre des diplômes du supérieur (licence, master, doctorat), ERA organise ses formations selon le système LMD : des <strong>filières</strong>, enseignées à certains <strong>niveaux</strong> (L1, L2, L3…), dont la <strong>maquette</strong> répartit les crédits en <strong>unités d&#39;enseignement (UE)</strong> composées d&#39;<strong>éléments constitutifs (EC)</strong>.</p><p>L&#39;espace s&#39;ouvre par <strong>Supérieur → Filières</strong>. Il apparaît si votre licence comprend l&#39;enseignement supérieur.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><p>Les filières vivent dans un <strong>département de type « Université »</strong>, avec ses niveaux. Créez-les d&#39;abord dans le paramétrage scolaire :</p><ol><li><strong>Paramétrage → Départements</strong> : un département de type <em>Université</em>, par exemple « Faculté des sciences ».</li><li><strong>Paramétrage → Niveaux</strong> : ses niveaux, dans l&#39;ordre (L1, L2, L3, M1, M2).</li></ol><h2 id="creer-une-filiere" tabindex="-1">Créer une filière <a class="header-anchor" href="#creer-une-filiere" aria-label="Permalink to &quot;Créer une filière&quot;">​</a></h2><p>Depuis <strong>Filières</strong>, le bouton <strong>Nouvelle filière</strong> demande :</p><ul><li>le <strong>département</strong> et le <strong>nom</strong> de la filière, avec un code facultatif (« INFO ») ;</li><li>le <strong>diplôme</strong> : licence, master ou doctorat ;</li><li>le <strong>rythme</strong> : semestriel par défaut, trimestriel ou annuel ;</li><li>les <strong>crédits par an</strong>, 60 par défaut. Ils se répartissent à parts égales entre les périodes : 30 par semestre en rythme semestriel ;</li><li>les <strong>niveaux enseignés</strong> : L1 à L3 pour une licence, L3 seule pour une licence professionnelle ;</li><li>ses <strong>responsables de filière</strong>.</li></ul><p>Le rythme et le département ne changent plus une fois la maquette commencée, et une filière qui a déjà une maquette ou des promotions ne peut pas être supprimée.</p><h2 id="les-responsables-de-filiere" tabindex="-1">Les responsables de filière <a class="header-anchor" href="#les-responsables-de-filiere" aria-label="Permalink to &quot;Les responsables de filière&quot;">​</a></h2><p>Un responsable de filière tient la maquette de <strong>sa</strong> filière, et de celle-là seulement. Ce n&#39;est pas un rôle à part : un enseignant ou un membre du personnel garde son rôle habituel et reçoit en plus l&#39;espace <strong>Supérieur</strong>, limité aux filières dont il a la charge. La création et la modification des filières restent réservées à l&#39;administrateur.</p><h2 id="construire-la-maquette" tabindex="-1">Construire la maquette <a class="header-anchor" href="#construire-la-maquette" aria-label="Permalink to &quot;Construire la maquette&quot;">​</a></h2><p>Le bouton <strong>Maquette</strong> d&#39;une filière ouvre sa maquette pour une année universitaire, choisie en haut de la page. Elle est présentée niveau par niveau, puis période par période.</p><ol><li><strong>Ajouter une UE</strong> dans la période voulue : un nom, un code facultatif, et si elle est <strong>optionnelle</strong> (proposée au choix).</li><li>Dans l&#39;UE, <strong>Ajouter un EC</strong> : son nom, ses <strong>crédits</strong>, son <strong>coefficient</strong> (par défaut égal aux crédits) et son volume horaire en CM, TD et TP.</li></ol><p>Les crédits sont portés par les EC : ceux d&#39;une UE sont la somme de ses EC, ils ne peuvent donc jamais se contredire.</p><div class="tip custom-block"><p class="custom-block-title">Le compteur de crédits</p><p>Chaque période affiche ses crédits face à ce qu&#39;elle doit porter, par exemple <strong>28 / 30 crédits</strong>. Il passe au vert quand le compte y est. Les UE optionnelles sont comptées à part : elles s&#39;ajoutent à l&#39;offre sans entrer dans ce que tout étudiant doit valider.</p></div><p>Les flèches réordonnent les UE d&#39;une période et les EC d&#39;une UE.</p><h2 id="une-maquette-par-annee" tabindex="-1">Une maquette par année <a class="header-anchor" href="#une-maquette-par-annee" aria-label="Permalink to &quot;Une maquette par année&quot;">​</a></h2><p>Chaque année universitaire a sa propre maquette. Modifier celle de cette année ne change jamais ce qu&#39;a suivi une promotion précédente.</p><p>Une nouvelle année démarre vide. ERA vous propose alors de <strong>reprendre la maquette de l&#39;année précédente</strong> en un clic : elle est copiée telle quelle, vous l&#39;ajustez ensuite. L&#39;ancienne reste intacte, et une année qui a déjà une maquette n&#39;est jamais écrasée.</p><p>Quand une année scolaire est <strong>clôturée</strong>, sa maquette l&#39;est aussi : elle reste consultable mais ne peut plus être modifiée.</p><h2 id="les-promotions" tabindex="-1">Les promotions <a class="header-anchor" href="#les-promotions" aria-label="Permalink to &quot;Les promotions&quot;">​</a></h2><p>Une <strong>promotion</strong> (par exemple « L1 Informatique 2026-2027 ») est une classe d&#39;un département universitaire. Lorsque vous créez une classe dans un tel département, ERA demande la <strong>filière</strong> qu&#39;elle suit, puis son <strong>niveau</strong>, choisi parmi ceux de la filière.</p>',24)])])}const g=t(a,[["render",i]]);export{c as __pageData,g as default};
